package com.b5studios.shared
import org.junit.Assert.*
import org.junit.Test
class ContentPolicyTest {
 private fun card()=mapOf<String,Any?>("id" to "test","title" to "My tool","body" to "Information","enabled" to true,"target" to "home")
 @Test fun publicHttpsAndEmailLinksWorkWithoutEmbeddedCredentials(){assertTrue(RemoteUrls.https("https://github.com/example/app/releases/download/v2/app.apk?download=1"));assertTrue(RemoteUrls.link("mailto:help@example.com"));for(value in listOf("http://example.com","javascript:alert(1)","https://user:secret@example.com","https://127.0.0.1/app.apk","https://host.local/app.apk"))assertFalse(RemoteUrls.https(value))}
 @Test fun updateDoesNotPromptForSameOrOlderVersionAndRequiredUpdatesCannotBeDismissed(){val update=AppUpdate(true,6,5,true,"https://example.com/client.apk","a".repeat(64));update.validate();assertTrue(update.offered(5));assertTrue(update.mandatory(5));assertFalse(update.offered(6));assertFalse(update.mandatory(7));assertFalse(update.copy(enabled=false).offered(1))}
 @Test fun updateNeedsRealDownloadAndChecksum(){for(update in listOf(AppUpdate(true,6,7),AppUpdate(true,6,1,false,"http://example.com/a.apk","a".repeat(64)),AppUpdate(true,6,1,false,"https://example.com/a.apk","bad"))){try{update.validate();fail("Invalid update accepted")}catch(_:IllegalArgumentException){}}}
 @Test fun sectionsSupportNativeActionsAndCodeButRejectUnknownActionsAndOversizedPrograms(){SectionPolicy.validate(listOf(card()+mapOf("action" to "connect")));SectionPolicy.validate(listOf(card()+mapOf("kind" to "code","html" to "<button>Go</button>","javascript" to "document.title='Tool'")));for(patch in listOf(mapOf("action" to "execute_native"),mapOf("kind" to "code","html" to ""),mapOf("kind" to "code","html" to "a".repeat(32769)))){try{SectionPolicy.validate(listOf(card()+patch));fail("Invalid section accepted")}catch(_:IllegalArgumentException){}}}
 @Test fun duplicateSectionIdsAndUnsafeLinksAreRejected(){try{SectionPolicy.validate(listOf(card(),card()));fail("duplicate accepted")}catch(_:IllegalArgumentException){};try{SectionPolicy.validate(listOf(card()+mapOf("action" to "link","url" to "javascript:alert(1)")));fail("unsafe link accepted")}catch(_:IllegalArgumentException){}}
 @Test fun arabicLabelsDoNotTranslateCodesOrSource(){assertEquals("تسجيل الدخول",AdminLanguage.translate("SIGN IN","ar"));assertEquals("USA-ABCD-EFGH",AdminLanguage.translate("USA-ABCD-EFGH","ar"));assertEquals("function main(){}",AdminLanguage.translate("function main(){}","ar"));assertEquals("SIGN IN",AdminLanguage.translate("SIGN IN","en"))}
}
